const signedXml =
  $json.xml_signed ||
  $json.signed_xml ||
  $json.signedXml ||
  $json.xml ||
  $json.xml_content ||
  $json.signed_document ||
  "";

if (!signedXml) {
  throw new Error(
    "Aucun XML signé trouvé. Le node Signature doit retourner xml_signed."
  );
}

// Extraire le numéro de facture depuis le XML signé
const match = signedXml.match(/<DocumentIdentifier>(.*?)<\/DocumentIdentifier>/);

const invoiceNumberRaw =
  $json.invoice_number && String($json.invoice_number).trim() !== ""
    ? $json.invoice_number
    : match
      ? match[1]
      : "invoice";

const invoiceNumber = String(invoiceNumberRaw)
  .trim()
  .replace(/[^\w\-]/g, "_");

const signedFileName = `${invoiceNumber}_signed.xml`;
const signedFilePath = `/shared/signed/${signedFileName}`;

return [
  {
    json: {
      invoice_number: invoiceNumber,
      signed_file_name: signedFileName,
      signed_file_path: signedFilePath,
      signed_xml: signedXml,
      signature_mode: $json.mode_used || "",
      legal_validity: $json.legal_validity || "",
      signature_type: $json.signature_type || "",
      signing_time: $json.signing_time || ""
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(signedXml, "utf8"),
        signedFileName,
        "application/xml"
      )
    }
  }
];

const xml = $json.xml;

if (!xml || typeof xml !== 'string') {
  throw new Error(
    `Le champ "xml" est vide ou introuvable. Champs reçus : ${Object.keys($json).join(', ')}`
  );
}

// Récupération du numéro de facture
const match = xml.match(
  /<DocumentIdentifier>\s*([^<]+?)\s*<\/DocumentIdentifier>/
);

const invoiceNumber = match
  ? match[1].trim().replace(/[\\/:*?"<>|]/g, '_')
  : 'invoice';

// Création du fichier XML binaire
const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(xml, 'utf8'),
  `${invoiceNumber}.xml`,
  'application/xml'
);

return [
  {
    json: {
      valid: $json.valid,
      stage: $json.stage,
      fileName: `${invoiceNumber}.xml`,
      invoice_number: invoiceNumber,
      xml_content: xml
    },
    binary: {
      data: binaryData
    }
  }
];

return items.map(item => {
  const restoredData =
    item.json.data ??
    item.json.corrected_data ??
    item.json;

  if (
    !restoredData ||
    typeof restoredData !== 'object' ||
    Array.isArray(restoredData)
  ) {
    throw new Error(
      'Données de facture introuvables. Champs disponibles : ' +
      JSON.stringify(Object.keys(item.json))
    );
  }

  return {
    json: restoredData,
    binary: item.binary,
  };
});

