parameters.jsCode:
const prepared =
  $('Préparer vérification humaine').first().json;

const submitted = $json.body ?? $json;

const originalData = prepared.original_data;

if (
  !originalData ||
  typeof originalData !== 'object' ||
  Array.isArray(originalData)
) {
  throw new Error(
    'original_data est absent dans Préparer vérification humaine.'
  );
}

const corrected = JSON.parse(
  JSON.stringify(originalData)
);

const decision =
  String(submitted.decision || 'REJECTED')
    .trim()
    .toUpperCase();

const correctionsText =
  String(submitted.corrections || '').trim();

const allowedFields = Array.isArray(prepared.error_fields)
  ? prepared.error_fields
  : [];

function getNestedValue(object, path) {
  return String(path)
    .split('.')
    .reduce(
      (current, key) => current?.[key],
      object
    );
}

function setNestedValue(object, path, value) {
  const keys = String(path).split('.');
  let cursor = object;

  for (let index = 0; index < keys.length - 1; index++) {
    const key = keys[index];

    if (
      cursor[key] === undefined ||
      cursor[key] === null ||
      typeof cursor[key] !== 'object'
    ) {
      cursor[key] = {};
    }

    cursor = cursor[key];
  }

  cursor[keys[keys.length - 1]] = value;
}

function resolveField(inputField) {
  const normalizedInput = String(inputField).trim();

  // Exemple : totaux.montant_tva
  if (allowedFields.includes(normalizedInput)) {
    return normalizedInput;
  }

  // Accepte aussi montant_tva
  const matches = allowedFields.filter(
    field =>
      String(field).split('.').pop() === normalizedInput
  );

  if (matches.length === 1) {
    return matches[0];
  }

  return null;
}

function parseValue(rawValue, originalValue) {
  const value = String(rawValue ?? '').trim();

  if (typeof originalValue === 'number') {
    const parsed = Number(
      value
        .replace(/\s/g, '')
        .replace(',', '.')
        .replace(/[^0-9.-]/g, '')
    );

    return Number.isFinite(parsed)
      ? parsed
      : originalValue;
  }

  return value;
}

const appliedCorrections = [];
const ignoredCorrections = [];

if (decision === 'APPROVED') {
  const lines = correctionsText
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);

  for (const line of lines) {
    const separatorIndex = line.indexOf('=');

    if (separatorIndex === -1) {
      ignoredCorrections.push({
        line,
        reason: 'Format invalide. Utiliser champ=valeur',
      });

      continue;
    }

    const enteredField = line
      .slice(0, separatorIndex)
      .trim();

    const rawValue = line
      .slice(separatorIndex + 1)
      .trim();

    const resolvedField = resolveField(enteredField);

    if (!resolvedField) {
      ignoredCorrections.push({
        field: enteredField,
        reason:
          'Ce champ ne figure pas dans les erreurs de validation',
      });

      continue;
    }

    const previousValue = getNestedValue(
      originalData,
      resolvedField
    );

    const newValue = parseValue(
      rawValue,
      previousValue
    );

    setNestedValue(
      corrected,
      resolvedField,
      newValue
    );

    appliedCorrections.push({
      field: resolvedField,
      previous_value: previousValue,
      new_value: newValue,
    });
  }
}

corrected.verification_humaine = {
  decision,
  reviewed_by: submitted.reviewed_by || '',
  commentaire: submitted.commentaire || '',
  reviewed_at: new Date().toISOString(),
  erreurs_initiales: prepared.validation_errors || [],
  corrections_appliquees: appliedCorrections,
  corrections_ignorees: ignoredCorrections,
};

return {
  json: {
    decision,
    corrected_data: corrected,
    applied_corrections: appliedCorrections,
    ignored_corrections: ignoredCorrections,
  },
};

// Remplacez "Validation" par le nom exact de votre nœud de validation
const input = $('Validation').first().json;

const allErrors = Array.isArray(input.errors)
  ? input.errors
  : [];

const warnings = Array.isArray(input.warnings)
  ? input.warnings
  : [];

// On conserve seulement les vrais champs modifiables.
// Les champs controle_validation.* sont calculés automatiquement.
const errors = allErrors.filter(error => {
  const field = String(error.field || '');

  return (
    field &&
    !field.startsWith('controle_validation.')
  );
});

const originalData = input.data;

if (
  !originalData ||
  typeof originalData !== 'object' ||
  Array.isArray(originalData)
) {
  throw new Error(
    'Le nœud Validation ne contient pas un objet data valide.'
  );
}

function getNestedValue(object, path) {
  return String(path)
    .split('.')
    .reduce(
      (current, key) => current?.[key],
      object
    );
}

const errorFields = errors
  .map(error => error.field)
  .filter(Boolean);

const currentErrorValues = {};

for (const field of errorFields) {
  currentErrorValues[field] = getNestedValue(
    originalData,
    field
  );
}

return {
  json: {
    review_status: 'PENDING_REVIEW',

    invoice_number:
      originalData.facture?.numero ||
      originalData.document?.numero ||
      '',

    currency:
      originalData.document?.devise || '',

    validation_stage:
      input.stage || 'json_extraction',

    validation_errors: errors,

    validation_warnings: warnings,

    error_fields: errorFields,

    current_error_values: currentErrorValues,

    review_reason: errors
      .map(error =>
        `${error.field}: ${error.message}`
      )
      .join(' | '),

    original_data: JSON.parse(
      JSON.stringify(originalData)
    ),

    review_created_at:
      new Date().toISOString(),
  },
};

const source =
  $json.data?.corrected_data ??
  $json.corrected_data ??
  $json;

// Copie indépendante compatible avec n8n
const corrected = JSON.parse(JSON.stringify(source));

if (
  !corrected ||
  typeof corrected !== 'object' ||
  Array.isArray(corrected)
) {
  throw new Error(
    `corrected_data absent ou invalide. Champs reçus : ${Object.keys($json).join(', ')}`
  );
}

// ============================================================
// DOCUMENT / FACTURE
// ============================================================

corrected.document =
  corrected.document &&
  typeof corrected.document === 'object' &&
  !Array.isArray(corrected.document)
    ? corrected.document
    : {};

corrected.facture =
  corrected.facture &&
  typeof corrected.facture === 'object' &&
  !Array.isArray(corrected.facture)
    ? corrected.facture
    : {};

corrected.facture.numero =
  corrected.facture.numero ||
  corrected.document.numero ||
  '';

corrected.facture.date_facture =
  corrected.facture.date_facture ||
  corrected.document.date ||
  '';

corrected.facture.date_echeance =
  corrected.facture.date_echeance ||
  corrected.document.date_echeance ||
  '';

corrected.facture.devise =
  corrected.facture.devise ||
  corrected.document.devise ||
  '';

corrected.facture.type_document =
  corrected.facture.type_document ||
  corrected.document.type_document ||
  '';

corrected.facture.code_type_document =
  corrected.facture.code_type_document ||
  corrected.document.code_type_document ||
  '';

// Synchroniser vers document
corrected.document.numero =
  corrected.document.numero ||
  corrected.facture.numero ||
  '';

corrected.document.date =
  corrected.document.date ||
  corrected.facture.date_facture ||
  '';

corrected.document.date_echeance =
  corrected.document.date_echeance ||
  corrected.facture.date_echeance ||
  '';

// ============================================================
// FOURNISSEUR / CLIENT
// ============================================================

corrected.fournisseur =
  corrected.fournisseur &&
  typeof corrected.fournisseur === 'object' &&
  !Array.isArray(corrected.fournisseur)
    ? corrected.fournisseur
    : {};

corrected.client =
  corrected.client &&
  typeof corrected.client === 'object' &&
  !Array.isArray(corrected.client)
    ? corrected.client
    : {};

if (corrected.client.nom) {
  corrected.client.nom = String(corrected.client.nom)
    .replace(/^à\s+/i, '')
    .trim();
}

// ============================================================
// APPLIQUER LES CORRECTIONS AVEC CHEMINS
// Exemple : lignes_facture[2].montant_ht
// ============================================================

function parsePath(path) {
  return String(path)
    .replace(/\[(\d+)\]/g, '.$1')
    .split('.')
    .filter(Boolean);
}

function setValueByPath(target, path, value) {
  const parts = parsePath(path);

  if (!parts.length) {
    return;
  }

  let current = target;

  for (let index = 0; index < parts.length - 1; index++) {
    const key = parts[index];
    const nextKey = parts[index + 1];
    const nextIsIndex = /^\d+$/.test(nextKey);

    if (
      current[key] === undefined ||
      current[key] === null ||
      typeof current[key] !== 'object'
    ) {
      current[key] = nextIsIndex ? [] : {};
    }

    current = current[key];
  }

  const finalKey = parts[parts.length - 1];

  current[finalKey] = value;
}

const corrections =
  $json.applied_corrections ??
  $json.data?.applied_corrections ??
  corrected.verification_humaine?.corrections_appliquees ??
  [];

for (const correction of corrections) {
  if (
    correction &&
    correction.field &&
    correction.new_value !== undefined
  ) {
    setValueByPath(
      corrected,
      correction.field,
      correction.new_value
    );
  }
}

// ============================================================
// SUPPRIMER LES FAUSSES CLÉS CRÉÉES COMME TEXTE
// Exemple : "lignes_facture[2]"
// ============================================================

for (const key of Object.keys(corrected)) {
  if (
    key.includes('[') &&
    key.includes(']')
  ) {
    delete corrected[key];
  }
}

// ============================================================
// LIGNES
// ============================================================

function parseJsonIfPossible(value) {
  if (typeof value !== 'string') {
    return value;
  }

  const trimmed = value.trim();

  if (!trimmed) {
    return [];
  }

  try {
    return JSON.parse(trimmed);
  } catch {
    return value;
  }
}

function toNumber(value, fallback = 0) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return fallback;
  }

  if (typeof value === 'number') {
    return Number.isFinite(value)
      ? value
      : fallback;
  }

  const normalized = String(value)
    .replace(/\s/g, '')
    .replace(',', '.')
    .replace(/[^0-9.-]/g, '');

  const parsed = Number(normalized);

  return Number.isFinite(parsed)
    ? parsed
    : fallback;
}

function normalizeLines(value) {
  value = parseJsonIfPossible(value);

  if (!value) {
    return [];
  }

  if (
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    value = [value];
  }

  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((line, index) => {
      line = parseJsonIfPossible(line);

      if (
        !line ||
        typeof line !== 'object' ||
        Array.isArray(line)
      ) {
        return null;
      }

      return {
        reference:
          line.reference ??
          line.ref ??
          line.code_article ??
          '',

        designation:
          line.designation ??
          line.description ??
          line.libelle ??
          '',

        quantite: toNumber(
          line.quantite ??
          line.quantity ??
          line.qte,
          0
        ),

        prix_unitaire: toNumber(
          line.prix_unitaire ??
          line.unit_price ??
          line.prix,
          0
        ),

        remise: toNumber(
          line.remise ??
          line.discount,
          0
        ),

        taux_tva: toNumber(
          line.taux_tva ??
          line.tax_rate ??
          line.tva,
          0
        ),

        montant_ht: toNumber(
          line.montant_ht ??
          line.line_total_ht ??
          line.total_ht,
          0
        ),

        numero_ligne:
          line.numero_ligne ??
          line.line_number ??
          index + 1
      };
    })
    .filter(Boolean);
}

const sourceLines =
  Array.isArray(corrected.lignes_facture) &&
  corrected.lignes_facture.length
    ? corrected.lignes_facture
    : corrected.lignes;

const normalizedLines = normalizeLines(sourceLines);

corrected.lignes = normalizedLines;
corrected.lignes_facture = normalizedLines;

// ============================================================
// TOTAUX
// ============================================================

corrected.totaux =
  corrected.totaux &&
  typeof corrected.totaux === 'object' &&
  !Array.isArray(corrected.totaux)
    ? corrected.totaux
    : {};

// ============================================================
// NETTOYAGE DES ENVELOPPES
// ============================================================

delete corrected.decision;
delete corrected.corrected_data;
delete corrected.applied_corrections;
delete corrected.ignored_corrections;

// ============================================================
// RÉSULTAT
// ============================================================

return [
  {
    json: corrected
  }
];
